from pathlib import Path
import json
base=Path.home()/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4'
task='A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2'
result=base/'model_results'/(task+'.json')
out={'result_exists':result.is_file()}
if result.is_file():
    try:r=json.loads(result.read_text(encoding='utf-8'))
    except Exception as e:r={'parse_error':type(e).__name__}
    if isinstance(r,dict):
        keys=('task_id','campaign_id','phase','decision','status','reviewer_model','model','model_policy','reasoning_effort','completion_sha256','prompt_sha256','input_sha256','proposal_task_id','proposal_completion_sha256','review_text','feedback','blocking_issues','created_at','completed_at')
        out['result']={k:r.get(k) for k in keys}
print('ERROR_CLASS=R4P2_PREBUILD_RESULT_DETAIL',flush=True)
print('ERROR='+json.dumps(out,separators=(',',':'),sort_keys=True),flush=True)
raise SystemExit(1)
